import java.io.IOException;
import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class ProblemE {
    public static int w, h;

    public static int MAX = 9999999;

    public static Set<Integer> result = new HashSet<Integer>();

    public static void dfs(int n, int m, int mask) {
        if (n >= w) {
            result.add(mask);
            return;
        }
        // Option 1: spider stays in place (moves down)
        dfs(n+1, m, mask | (1 << (n + w)));
        // Option 2: spider moves up (from row 0, can't move up)
        if (m > 0) {
            dfs(n+1, m, mask | (1 << n));
        }
        // Option 3: spider moves down (from last row, can't move down)
        if (m < h - 1) {
            dfs(n+1, m, mask | (1 << (n + w*2)));
        }
        // Option 4: spider moves left
        if (n > 0) {
            dfs(n+1, m, mask | (1 << ((n-1) + w)));
        }
        // Option 5: spider moves right
        if (n < w - 1) {
            dfs(n+1, m, mask | (1 << ((n+1) + w)));
        }
    }

    public static void main(String[] args) throws IOException {
        Scanner s = new Scanner(System.in);
        String[] line = s.nextLine().split(" ");
        w = Integer.valueOf(line[0]);
        h = Integer.valueOf(line[1]);

        // dp[i][mask] = minimum number of occupied cells after processing i rows
        int[][] dp = new int[h+1][1<<(w*3)];
        for (int i = 0 ; i <= h ; i++) {
            for (int j = 0 ; j < 1<<(w*3) ; j++) {
                dp[i][j] = MAX;
            }
        }
        dp[0][0] = 0;

        for (int i = 0 ; i < h ; i++) {
            result.clear();
            dfs(0, i, 0);
            for (int j = 0 ; j < 1<<(w*3) ; j++) {
                if (dp[i][j] != MAX) {
                    for (int res : result) {
                        // res represents where spiders from row i can move to
                        // j represents occupied positions in previous rows that affect current row
                        int next = res;
                        // Count how many spiders end up in the current row (row i)
                        int occupiedInCurrentRow = Integer.bitCount(next & ((1<<w) - 1)) +
                                                   Integer.bitCount((next >> w) & ((1<<w) - 1)) +
                                                   Integer.bitCount((next >> (w*2)) & ((1<<w) - 1));
                        dp[i+1][next] = Math.min(dp[i+1][next], dp[i][j] + occupiedInCurrentRow);
                    }
                }
            }
        }

        int answer = MAX;
        for (int j = 0 ; j < 1<<(w*3) ; j++) {
            if (dp[h][j] != MAX) {
                answer = Math.min(answer, dp[h][j]);
            }
        }
        System.out.println(h * w - answer);
    }
}
</source_code>
